function InquiryForm({ submitted, setSubmitted, dark }) {
  const [data, setData] = useState({ firstName: "", lastName: "", subject: "", message: "" });

  if (submitted) {
    return (
      <div className="text-center py-16" style={{ color: dark ? "var(--cream)" : "var(--ink)" }}>
        <Check className="mx-auto mb-6 gold" size={36} />
        <div className="display text-3xl mb-2">Благодарим!</div>
        <p className="text-sm" style={{ color: dark ? "var(--cream)" : "var(--muted)", opacity: dark ? 0.8 : 1 }}>
          Запитването Ви е изпратено. Ще Ви отговорим в най-кратък срок на посочения имейл.
        </p>
        <button className="mt-8 underline-link text-xs uppercase tracking-widest" onClick={() => { setSubmitted(false); setData({ firstName: "", lastName: "", subject: "", message: "" }); }}>
          Изпратете ново запитване
        </button>
      </div>
    );
  }

  const inputStyle = dark ? { borderColor: "rgba(246,241,230,0.3)", color: "var(--cream)" } : {};
  const labelStyle = dark ? { color: "rgba(246,241,230,0.6)" } : {};

  return (
    <form onSubmit={(e) => { e.preventDefault(); setSubmitted(true); }} className="space-y-7">
      <div className="grid grid-cols-2 gap-5">
        <div>
          <div className="label mb-2" style={labelStyle}>Име</div>
          <input className="input" required value={data.firstName} onChange={e => setData({...data, firstName: e.target.value})} style={inputStyle} />
        </div>
        <div>
          <div className="label mb-2" style={labelStyle}>Фамилия</div>
          <input className="input" required value={data.lastName} onChange={e => setData({...data, lastName: e.target.value})} style={inputStyle} />
        </div>
      </div>
      <div>
        <div className="label mb-2" style={labelStyle}>Предмет</div>
        <input className="input" required placeholder="Математика, български, немски, история, природни науки..." value={data.subject} onChange={e => setData({...data, subject: e.target.value})} style={inputStyle} />
      </div>
      <div>
        <div className="label mb-2" style={labelStyle}>Запитване</div>
        <textarea className="input" required rows={4} value={data.message} onChange={e => setData({...data, message: e.target.value})} style={{ ...inputStyle, resize: "vertical" }} />
      </div>
      <button type="submit" className="btn-primary" style={dark ? { background: "var(--gold)", borderColor: "var(--gold)", color: "var(--ink)" } : {}}>
        Изпратете запитване <Send size={14} />
      </button>
      <p className="text-xs" style={{ color: dark ? "rgba(246,241,230,0.6)" : "var(--muted)" }}>
        Запитванията се изпращат на zlatnotosechenie@abv.bg
      </p>
    </form>
  );
}

function EnrollModal({ course, submitted, onClose, onSubmit }) {
  const [data, setData] = useState({
    studentFirst: "", studentLast: "", parentFirst: "", parentLast: "", email: "", phone: ""
  });

  return (
    <div className="fixed inset-0 z-50 modal-bg flex items-center justify-center p-4 overflow-y-auto" onClick={onClose}>
      <div onClick={e => e.stopPropagation()} className="relative w-full max-w-2xl my-8" style={{ background: "var(--cream)", border: "1px solid var(--line)" }}>
        <button onClick={onClose} className="absolute top-5 right-5 p-2" aria-label="Затвори"><X size={20} /></button>

        {submitted ? (
          <div className="p-12 text-center">
            <Check className="mx-auto gold mb-6" size={42} />
            <div className="display text-4xl mb-3">Заявката е изпратена.</div>
            <p className="text-base mb-2" style={{ color: "var(--ink-soft)" }}>
              Записването Ви за <span className="display-i gold">{course.grade}{course.subject ? ` (${course.subject})` : ""} · {course.mode}</span>
            </p>
            <p className="text-sm leading-relaxed max-w-md mx-auto mb-8" style={{ color: "var(--muted)" }}>
              Ще получите потвърждение и инструкции за първото плащане на посочения имейл. Очакваме Ви!
            </p>
            <button className="btn-primary" onClick={onClose}>Затвори</button>
          </div>
        ) : (
          <div className="p-8 lg:p-12">
            <div className="small-caps gold mb-3">Записване</div>
            <div className="display text-3xl lg:text-4xl mb-1">{course.grade}{course.subject ? ` · ${course.subject}` : ""}</div>
            <div className="display-i text-lg mb-2" style={{ color: "var(--muted)" }}>
              {course.mode} · {course.teacher} · {course.price}
            </div>
            <div className="gold-line my-8" />

            <form onSubmit={e => { e.preventDefault(); onSubmit(); }} className="space-y-7">
              <div>
                <div className="small-caps mb-4" style={{ color: "var(--gold-deep)" }}>Ученик</div>
                <div className="grid grid-cols-2 gap-5">
                  <div><div className="label mb-2">Име</div><input className="input" required value={data.studentFirst} onChange={e => setData({...data, studentFirst: e.target.value})} /></div>
                  <div><div className="label mb-2">Фамилия</div><input className="input" required value={data.studentLast} onChange={e => setData({...data, studentLast: e.target.value})} /></div>
                </div>
              </div>
              <div>
                <div className="small-caps mb-4" style={{ color: "var(--gold-deep)" }}>Родител</div>
                <div className="grid grid-cols-2 gap-5">
                  <div><div className="label mb-2">Име</div><input className="input" required value={data.parentFirst} onChange={e => setData({...data, parentFirst: e.target.value})} /></div>
                  <div><div className="label mb-2">Фамилия</div><input className="input" required value={data.parentLast} onChange={e => setData({...data, parentLast: e.target.value})} /></div>
                </div>
              </div>
              <div>
                <div className="small-caps mb-4" style={{ color: "var(--gold-deep)" }}>За контакт</div>
                <div className="grid grid-cols-2 gap-5">
                  <div><div className="label mb-2">Имейл</div><input className="input" type="email" required value={data.email} onChange={e => setData({...data, email: e.target.value})} /></div>
                  <div><div className="label mb-2">Телефон</div><input className="input" type="tel" required value={data.phone} onChange={e => setData({...data, phone: e.target.value})} /></div>
                </div>
              </div>

              <div className="p-5 text-xs leading-relaxed" style={{ background: "var(--cream-deep)", color: "var(--ink-soft)" }}>
                <strong>Условия за плащане.</strong>{" "}
                {course.mode === "Онлайн" ? (
                  <>Курсът е организиран в 3 модула по 11 занятия. Едно занятие — 21 €, целият модул — 231 €. Първият модул се плаща при записване, вторият — през декември, а третият — през март.</>
                ) : (
                  <>Месечната такса е {course.price} (в зависимост от месеца — броя на занятията). Плаща се веднъж месечно, между 1-во и 10-то число. Първото плащане е дължимо при записване. Цена на едно занятие — 50 €.</>
                )}
              </div>

              <div className="flex gap-3 pt-2">
                <button type="submit" className="btn-primary flex-1 justify-center">Потвърди записване <ChevronRight size={16} /></button>
                <button type="button" className="btn-ghost" onClick={onClose}>Отказ</button>
              </div>
            </form>
          </div>
        )}
      </div>
    </div>
  );
}
